{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min:
        raise ValueError("Budget below total minimum")
    if budget > total_cap:
        raise ValueError("Budget exceeds total capacity")
    allocs = [s['minimum'] for s in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if allocs[i] >= s['capacity']:
                continue
            score = s['importance'] / (allocs[i] + 1)
            if score > best_score or (score == best_score and i < best_idx):
                best_score = score
                best_idx = i
        if best_idx == -1:
            raise ValueError("No available capacity")
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocs[i] for i in range(n)}
    total = sum(allocs)
    return {"allocations": allocs, "by_name": by_name, "total": total}
